// DecodeApprovalEvent decodes a "Approval(address,address,uint256)" log.
func (c *ILiquidStakedDSBinding) DecodeApprovalEvent(log types.Log) (out ILiquidStakedDSApprovalEvent, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI event: %v", failure)
		}
	}()
	definition, err := c.event("Approval(address,address,uint256)")
	if err != nil {
		return out, err
	}
	if len(log.Topics) == 0 || log.Topics[0] != definition.ID {
		return out, fmt.Errorf("event signature mismatch for %s", "Approval(address,address,uint256)")
	}
	if len(log.Topics) != 3 {
		return out, fmt.Errorf("event topic count mismatch for %s", "Approval(address,address,uint256)")
	}
	if len(definition.Inputs.NonIndexed()) > 0 {
		values, err := definition.Inputs.NonIndexed().Unpack(log.Data)
		if err != nil {
			return out, err
		}
		if len(values) != 1 {
			return out, fmt.Errorf("event value count mismatch")
		}
		out.Amount = *abi.ConvertType(values[0], new(*big.Int)).(**big.Int)
	} else if len(log.Data) != 0 {
		return out, fmt.Errorf("unexpected event data")
	}
	var indexed abi.Arguments
	var indexedTopics []common.Hash
	indexed = append(indexed, definition.Inputs[0])
	indexedTopics = append(indexedTopics, log.Topics[1])
	indexed = append(indexed, definition.Inputs[1])
	indexedTopics = append(indexedTopics, log.Topics[2])
	if err := abi.ParseTopics(&out, indexed, indexedTopics); err != nil {
		return out, err
	}
	return out, nil
}

// FilterApproval retrieves and decodes "Approval(address,address,uint256)" logs. Indexed filters follow ABI order.
func (c *ILiquidStakedDSBinding) FilterApproval(ctx context.Context, from, to *big.Int, indexed ...[]any) ([]ILiquidStakedDSApprovalEvent, error) {
	if c.backend == nil {
		return nil, fmt.Errorf("ILiquidStakedDSBinding has no backend")
	}
	definition, err := c.event("Approval(address,address,uint256)")
	if err != nil {
		return nil, err
	}
	count := 0
	for _, arg := range definition.Inputs {
		if arg.Indexed {
			count++
		}
	}
	if len(indexed) > count {
		return nil, fmt.Errorf("too many indexed filters for %s", "Approval(address,address,uint256)")
	}
	queries := indexed
	queries = append([][]any{{definition.ID}}, queries...)
	topics, err := abi.MakeTopics(queries...)
	if err != nil {
		return nil, err
	}
	logs, err := c.backend.FilterLogs(ctx, ethereum.FilterQuery{Addresses: []common.Address{c.address}, Topics: topics, FromBlock: from, ToBlock: to})
	if err != nil {
		return nil, err
	}
	out := make([]ILiquidStakedDSApprovalEvent, 0, len(logs))
	for _, log := range logs {
		decoded, err := c.DecodeApprovalEvent(log)
		if err != nil {
			return nil, err
		}
		out = append(out, decoded)
	}
	return out, nil
}

// WatchApproval subscribes to new "Approval(address,address,uint256)" logs and decodes them. Call Unsubscribe on the returned subscription when done.
func (c *ILiquidStakedDSBinding) WatchApproval(ctx context.Context, indexed ...[]any) (<-chan ILiquidStakedDSApprovalEvent, event.Subscription, error) {
	if c.backend == nil {
		return nil, nil, fmt.Errorf("ILiquidStakedDSBinding has no backend")
	}
	definition, err := c.event("Approval(address,address,uint256)")
	if err != nil {
		return nil, nil, err
	}
	count := 0
	for _, arg := range definition.Inputs {
		if arg.Indexed {
			count++
		}
	}
	if len(indexed) > count {
		return nil, nil, fmt.Errorf("too many indexed filters for %s", "Approval(address,address,uint256)")
	}
	queries := indexed
	queries = append([][]any{{definition.ID}}, queries...)
	topics, err := abi.MakeTopics(queries...)
	if err != nil {
		return nil, nil, err
	}
	logs := make(chan types.Log)
	upstream, err := c.backend.SubscribeFilterLogs(ctx, ethereum.FilterQuery{Addresses: []common.Address{c.address}, Topics: topics}, logs)
	if err != nil {
		return nil, nil, err
	}
	events := make(chan ILiquidStakedDSApprovalEvent)
	subscription := event.NewSubscription(func(quit <-chan struct{}) error {
		defer upstream.Unsubscribe()
		defer close(events)
		for {
			select {
			case <-quit:
				return nil
			case <-ctx.Done():
				return ctx.Err()
			case err, ok := <-upstream.Err():
				if !ok {
					return nil
				}
				return err
			case log, ok := <-logs:
				if !ok {
					return nil
				}
				decoded, err := c.DecodeApprovalEvent(log)
				if err != nil {
					return err
				}
				select {
				case events <- decoded:
				case <-quit:
					return nil
				case <-ctx.Done():
					return ctx.Err()
				}
			}
		}
	})
	return events, subscription, nil
}

