// DecodeInsufficientAllowanceError decodes a "InsufficientAllowance(address,uint256,uint256)" revert payload, including its selector.
func (c *ILiquidStakedDSBinding) DecodeInsufficientAllowanceError(raw []byte) (out ILiquidStakedDSInsufficientAllowanceError, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI error: %v", failure)
		}
	}()
	definition, err := c.customError("InsufficientAllowance(address,uint256,uint256)")
	if err != nil {
		return out, err
	}
	if len(raw) < 4 || !bytes.Equal(raw[:4], definition.ID[:4]) {
		return out, fmt.Errorf("error selector mismatch for %s", "InsufficientAllowance(address,uint256,uint256)")
	}
	values, err := definition.Inputs.Unpack(raw[4:])
	if err != nil {
		return out, err
	}
	if len(values) != 3 {
		return out, fmt.Errorf("error value count mismatch")
	}
	out.Spender = *abi.ConvertType(values[0], new(common.Address)).(*common.Address)
	out.Allowance = *abi.ConvertType(values[1], new(*big.Int)).(**big.Int)
	out.Needed = *abi.ConvertType(values[2], new(*big.Int)).(**big.Int)
	return out, nil
}

