// DecodeError identifies and decodes a declared custom error.
func (c *ILiquidStakedDSBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("InsufficientAllowance(address,uint256,uint256)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInsufficientAllowanceError(raw)
	}
	if definition, err := c.customError("InsufficientBalance(address,uint256,uint256)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInsufficientBalanceError(raw)
	}
	if definition, err := c.customError("TransferToZeroAddress()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeTransferToZeroAddressError(raw)
	}
	if definition, err := c.customError("Unauthorized()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeUnauthorizedError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
